import sys

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        n = int(input[ptr])
        ptr += 1
        s = input[ptr]
        ptr += 1
        res = float('inf')
        for c in 'abcdefghijklmnopqrstuvwxyz':
            temp = []
            cnt = 0
            for ch in s:
                if ch == c:
                    cnt += 1
                else:
                    temp.append(ch)
            temp_str = ''.join(temp)
            l, r = 0, len(temp_str) - 1
            is_pal = True
            while l < r:
                if temp_str[l] != temp_str[r]:
                    is_pal = False
                    break
                l += 1
                r -= 1
            if is_pal:
                res = min(res, cnt)
        if res != float('inf'):
            print(res)
        else:
            print(-1)

solve()
